def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def sections(length, separators):
        result, start = [], 0
        for s in separators:
            if s > start:
                result.append((start, s))
            start = s + 1
        if start < length:
            result.append((start, length))
        return result

    rs, cs = sections(h, sep_rows), sections(w, sep_cols)
    boxes = [(a, b, x, y) for a, b in rs for x, y in cs]
    def score(box):
        a, b, x, y = box
        return sum(grid[r][c] != background for r in range(a, b) for c in range(x, y))
    src = max(boxes, key=score)
    a, b, x, y = src
    tile = [row[x:y] for row in grid[a:b]]
    out = [row[:] for row in grid]
    for r0, r1 in rs:
        for c0, c1 in cs:
            if r1-r0 == len(tile) and c1-c0 == len(tile[0]):
                for i in range(len(tile)):
                    out[r0+i][c0:c1] = tile[i][:]
    return out
